-- [[
-- Bloodmoon_Raid_Controller_II (445548) -- Bloodmoon raid controller (version 2).
-- Registers the raid win chest as a loot event on instance boot and adds a
-- 72h lockout when the encounter signals completion. Passive, non-combat.
-- Rasper: raidBloodmoon2.html. Generated by gen_bloodmoon_raid.py -- do not hand-edit.
-- ]]
local M = require("sof_bloodmoon_raid")
local LOCKOUT = eq.seconds("72h")
local EVENT = { name = "Bloodmoon: Crazok Moonfang", chest = 445541 }

function event_spawn(e)
	local exp = eq.get_expedition()
	if not exp.valid then return end
	exp:SetLootEventByNPCTypeID(EVENT.chest, EVENT.name)

end

function event_signal(e)
	if e.signal ~= 1102 then return end
	local exp = eq.get_expedition()
	if exp.valid and not exp:HasLockout(EVENT.name) then
		exp:AddLockout(EVENT.name, LOCKOUT)
		eq.zone_emote(15, EVENT.name .. " has been defeated!")
	end
end
